add(c,20,'MC',3,'3.IP3','（주어 누락）는 다음 중 무엇에 의해 세포내 효과를 생성하는가?',['activating protein kinase C','activating protein kinase A','releasing intracellular calcium','activating adenylate cyclase','activating guanylate cyclase'],[3],'교차확인',[k15(20,'③'),t4('ip3')],nt='[원문] “는 다음 중 무엇에 의해 세포내 효과를 생성하는가?” (주어가 기호로 쓰여 추출 누락) [수정 제안] “IP3는 …” [사유] 보기 ③ releasing intracellular calcium과 정합(교안 p.19). 22학번 22번 “IP3은 …”과 동형.')
add(c,21,'MC',3,'3.kinase-linked','다음 중 insulin hormone 작용에 포함된 세포막 신호전달기전을 가장 정확하게 설명한 것은?',['세포막에 걸쳐있는 tyrosine kinase에 대한 작용','adenylate cyclase를 활성화 하거나 억제하는 g-protein의 활성화','세포막을 통해 확산되어 세포막 내 수용체와의 결합','세포막을 통과하는 STAT molecule의 확산','세포막 ion channel의 열림'],[1],'교차확인',[k15(21,'①'),t4('klgf')],nt='교안 p.25는 growth factor 수용체를 tyrosine kinase 내장형으로 서술. insulin은 교안 p.5 표에서 Type 3 예시로 표기(그림 텍스트).')
add(c,22,'MC',2,'2.partial-agonist','다른 약물의 부재시 pindolol은 β receptor의 활성화를 통해 심박수 의 증가를 일으킨다. 그러나 매우 효능이 큰 β receptor agonist의 존재 시에는 pindolol은 용량의존적으로 심박수의 가역적 감소를 일으킨다. 다음 중 pindolol에 대한 설명으로 가장 적합한 것은?',['chemical antagonist','irreversible antagonist','partial agonist','physiologic antagonist','spare receptor agonist'],[3],'교차확인',[k15(22,'③'),t4('partial')],nt='pindolol 사례는 교안에 없고 partial agonist 정의만 교안(p.10).')
add(c,23,'MC',2,'2.potency','심부전을 가진 55세의 여성이 이뇨제로 치료를 받으려 한다. 약물 X 와 Y는 같은 기전을 가진 이뇨제이다. 5mg의 약물 X는 500mg의 약물 Y와 같은 정도의 이뇨작용을 나타낸다. 다음 중 가장 올바르게 설명된 것은?',['약물 Y는 약물 X보다 효능이 적다.','약물 X는 약물 Y보다 100대 더 효력이 크다.','약물 X의 독성은 약물 Y보다 적다.','약물 X는 약물 Y보다 더 넓은 치료범위를 갖고 있다.','약물작용 기간동안 약물 X가 더 적은 양 존재하므로 약물 X의 작용 지속 시간이 약물 Y보다 더 짧다.'],[2],'추정',[k15(23,'②')],conf='중',nt='potency(효력)=같은 효과에 필요한 용량 비교. 교안에 정의 없음(교안 근거 없음).',orig='원문 “100대” [수정 제안] 100배 [사유] 오타 추정(5mg:500mg=100배).')
add(c,24,'MC',2,'2.chemical-antagonism','67세 남성이 정맥 혈전증으로 응급실에 실려와 항응고제인 heparin을 투여받았다. 불행히도 농도 조절에 실패하여 과량의 heparin이 투여되어 부작용이 발생되었다. 해독제로 protamine을 투여하였으며 이는 heparin 과 이온쌍으로 결합하여 heparin의 작용을 방해한다. 이 두 약물의 상호 작용을 가장 잘 설명한 것은?',['competitive antagonism','chemical antagonism','physiolgical antagonism','pharmacokinetic antagonism','inverse agonist'],[2],'교차확인',[k15(24,'②'),t4('chem')])
add(c,25,'MC',2,'2.potency-table','두 개의 콜레스테롤 저하약물 X와 Y가 큰 규모의 환자군에서 연구되어 특정 치료효과 (LDL 콜레스테롤의 20%감소)가 나타난 환자의 바율 이 측정되었다. 그 결과는 다음 표와 같다. 다음 설명 중 올바른 것은?\n[표] 용량(mg): 5/10/20/50/100/200 → 약물 X 반응(%): 1/5/10/50/70/90, 약물 Y 반응(%): 10/20/50/70/90/100',['약물 X가 약물 Y보다 더 안전하다.','약물 Y가 약물 X보다 더 효능이 크다.','두 약물이 같은 수용체에 작용한다.','약물 X가 약물 Y보다 효력이 작다.','약물 Y의 치료지수는 10이다.'],[4],'추정',[k15(25,'④')],conf='중',nt='표는 원본 사진 대신 수치로 전사. 20학번 48번 동형(답 ③ 효력이 더 작다).',orig='원문 “바율” [수정 제안] 비율 [사유] 오타 추정.')
