add(c,35,'BK',2,'2.occupation','수용체와 가역적으로 결합하는 약물에 의해 나타나는 약리반응의 크기는 약물이 점유하고 있는 수용체의 수(분획)에 비례한다는 이론을 무엇이라고 하는가?',a='점유이론(occupation theory)',st='교차확인',ev=[k15(35,'점유이론(손글씨 판독 일부)'),t4('occ')],nt='정답표 35)가 “점유이론”으로 추출됨.')
add(c,36,'BK',2,'2.TI','therapeutic index (TI)를 구하는 공식을 쓰시오.',a='TI = TD50/ED50',st='교차확인',ev=[k15(36,'TD50/ED50'),t4('ti')])
add(c,37,'BK',2,'2.two-state','아래 그림은 two-state model을 제시하고 있다. agonist, antagonist, inverse agonist를 괄호에 맞게 각각 채워 넣으시오.',a='inverse agonist, agonist, antagonist (그림의 위 왼쪽→위 오른쪽→아래 순)',st='교차확인',ev=[k15(37,'inverse agonist, agonist, antagonist'),t4('two'),t4('inv')],fig='f20_23',nt='원본 사진에 정답 손글씨가 있어 내장하지 않고 20학번 동형 문항의 깨끗한 그림으로 대체함.')
add(c,38,'DS',2,'2.dose-response-scale','다음 그림은 약물의 용량 반응 관계를 나타내는 그래프로 같은 약물에 대하여 왼쪽은 대수척도를 사용한 로그 약물농도 대 약물반응의 크기로 나타낸 것이고, 오른쪽의 그래프는 산술척도를 사용하여 나타낸 것이다. 두 그래프를 비교하였을 때, 어느 그래프가 더 유용한지, 그 이유는 무엇인지 설명하여라.',a='대수척도(로그) 그래프가 더 유용: 넓은 용량 범위를 한 그래프에 나타내 S자 곡선으로 관찰·비교가 수월함.',st='추정',ev=[k15(38,'더 관찰과 비교가 수월하다.'),['T4','2026 교안 Ch.2','p.22','Dose-effect curves for two drugs differing in receptor affinity by a factor of 1000. Left, A log scale. Right, An arithmetic scale.']],conf='중',fig='f15_38',figreveal=True,nt='교안 p.22는 그림 캡션만 있고 이유 서술 없음. 원본 그림에 정답 손글씨(“대수척도”)가 있어 정답 보기 후에만 표시.')
add(c,39,'DS',3,'3.PAR','g-protein coupled receptor의 한 종류인 protease-activated receptor의 활성화와 불활성화 기전을 설명하여라.',a='N-terminal extracellular domain이 단백질분해효소(thrombin 등)에 의해 절단되어 활성화되고, 인산화(phosphorylation)로 불활성화됨.',st='교차확인',ev=[k15(39,'트롬빈이 N terminal 절단을 함으로 active. … phosphorylation이 일어나면 inactive'),t4('par_cl')],nt='회복에는 수용체의 재합성이 필요(교안 p.13 캡션).')
